import shutil
import math
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = wb.active.title
ws = wb[sheet_name]
vws = vals[sheet_name]

ranges = []
for r in range(2, vws.max_row + 1):
    a = vws.cell(row=r, column=1).value
    b = vws.cell(row=r, column=2).value
    c = vws.cell(row=r, column=3).value

    if a is None or b is None or c is None:
        continue

    try:
        a_f = float(a)
        b_f = float(b)
    except (TypeError, ValueError):
        continue

    if isinstance(c, float) and c.is_integer():
        c = int(c)

    ranges.append((a_f, b_f, c))

ranges.sort(key=lambda x: x[0])

def result_for(value):
    if value is None:
        return None

    try:
        v = float(value)
    except (TypeError, ValueError):
        return None

    for a, b, c in ranges:
        if a <= v <= b:
            return c

    if v == 0:
        return 1

    return int(math.ceil(v / 1000))

for r in range(2, 7):
    input_value = vws.cell(row=r, column=5).value
    result = result_for(input_value)
    ws.cell(row=r, column=6).value = result
    print(f"row {r}: input={input_value}, result={result}")

wb.save(OUT)
